return [{
  json: {
    // CHANGE THIS to the root URL of your ntfy server.
    // Examples:
    //   https://ntfy.sh
    //   https://ntfy.yourdomain.com
    ntfyUrl: 'https://ntfy.nhnj.us',

    ntfyTopic: 'ORU',

    metadataUrl: 'https://outagemap.oru.com/resources/data/external/interval_generation_data/metadata.json',
    mapUrl: 'https://outagemap.oru.com/external/default.html',

    // First successful run:
    // true  = send if there are active outages
    // false = silently establish the first baseline
    sendFirstRunIfActive: true,
  }
}];

const input = $input.first().json;

function parseMaybe(value) {
  if (value == null) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;

  const text = value.trim();
  if (!text) return null;

  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

let metadata = null;

if (input.directory) {
  metadata = input;
} else {
  metadata =
    parseMaybe(input.data) ||
    parseMaybe(input.body) ||
    parseMaybe(input);
}

if (!metadata?.directory) {
  throw new Error(`ORU metadata did not contain a directory. Received: ${JSON.stringify(input).slice(0, 500)}`);
}

const directory = String(metadata.directory).trim();

if (!/^\d{4}_\d{2}_\d{2}_\d{2}_\d{2}_\d{2}$/.test(directory)) {
  throw new Error(`Unexpected ORU generation directory: ${directory}`);
}

const base =
  `https://outagemap.oru.com/resources/data/external/interval_generation_data/${directory}`;

const cacheBust = Date.now();

return [{
  json: {
    directory,
    njUrl: `${base}/report_nj.json?_=${cacheBust}`,
    nyUrl: `${base}/report_ny.json?_=${cacheBust}`,
  }
}];

const cfg = $('Config').first().json;
const directory = $('Build URLs').first().json.directory;

function parseResponse(nodeName) {
  const input = $(nodeName).first().json;

  if (input?.file_data?.areas) return input;

  const candidates = [
    input?.data,
    input?.body,
    input?.response,
  ];

  for (const value of candidates) {
    if (value && typeof value === 'object' && value.file_data?.areas) {
      return value;
    }

    if (typeof value === 'string') {
      const text = value.trim();
      if (!text) continue;

      try {
        const parsed = JSON.parse(text);
        if (parsed?.file_data?.areas) return parsed;
      } catch {}
    }
  }

  throw new Error(
    `${nodeName} did not return a valid ORU report. ` +
    `Received: ${JSON.stringify(input).slice(0, 750)}`
  );
}

function n(value) {
  const x = Number(value ?? 0);
  return Number.isFinite(x) ? x : 0;
}

function titleCase(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\b([a-z])/g, m => m.toUpperCase());
}

function normalizeEtr(raw) {
  const value = String(raw || '').trim();

  if (!value || value === 'ETR-NULL') return '';
  return value;
}

function displayEtr(raw) {
  const value = normalizeEtr(raw);

  if (!value) return '--';
  if (value === 'ETR-EXP') return 'Pending';

  if (/^\d{4}-\d{2}-\d{2}T/.test(value)) {
    const d = new Date(value);

    if (!Number.isNaN(d.getTime())) {
      return new Intl.DateTimeFormat('en-US', {
        timeZone: 'America/New_York',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
      }).format(d);
    }
  }

  return value.replace(/^ETR-/, '');
}

function formatNumber(value) {
  return n(value).toLocaleString('en-US');
}

function percentLabel(out, served) {
  out = n(out);
  served = n(served);

  if (out <= 0 || served <= 0) return '0%';

  const pct = (out / served) * 100;

  if (pct < 0.1) return '<0.1%';
  if (pct < 10) return `${pct.toFixed(1)}%`;

  return `${Math.round(pct)}%`;
}

function generationTime(dir) {
  const m = String(dir).match(
    /^(\d{4})_(\d{2})_(\d{2})_(\d{2})_(\d{2})_(\d{2})$/
  );

  if (!m) {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(new Date());
  }

  // The ORU generation directory is UTC.
  const d = new Date(Date.UTC(
    Number(m[1]),
    Number(m[2]) - 1,
    Number(m[3]),
    Number(m[4]),
    Number(m[5]),
    Number(m[6]),
  ));

  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(d);
}

function normalizeReport(report, state) {
  const root = report?.file_data?.areas?.[0];

  if (!root || !Array.isArray(root.areas)) {
    throw new Error(`${state} ORU report has an unexpected structure.`);
  }

  const counties = root.areas.map(county => {
    const towns = Array.isArray(county.areas) ? county.areas : [];

    const activeTowns = towns
      .filter(town => n(town?.cust_a?.val) > 0)
      .map(town => ({
        municipality: titleCase(town.area_name),
        customersOut: n(town?.cust_a?.val),
        customersServed: n(town?.cust_s),
        etrRaw: normalizeEtr(town?.etr),
        etr: displayEtr(town?.etr),
      }))
      .sort((a, b) => a.municipality.localeCompare(b.municipality));

    return {
      state,
      county: titleCase(county.area_name),
      customersOut: n(county?.cust_a?.val),
      customersServed: n(county?.cust_s),
      totalOutages: n(county?.total_outages),
      municipalities: activeTowns,
    };
  });

  counties.sort((a, b) => a.county.localeCompare(b.county));

  return {
    state,
    customersOut: n(root?.cust_a?.val),
    customersServed: n(root?.cust_s),
    totalOutages: n(root?.total_outages),
    counties,
  };
}

const nj = normalizeReport(parseResponse('Fetch NJ'), 'NJ');
const ny = normalizeReport(parseResponse('Fetch NY'), 'NY');

const states = [nj, ny];
const counties = states.flatMap(s => s.counties);

const totalCustomersOut = states.reduce((sum, s) => sum + s.customersOut, 0);
const totalOutages = states.reduce((sum, s) => sum + s.totalOutages, 0);
const activeMunicipalities = counties.reduce(
  (sum, county) => sum + county.municipalities.length,
  0
);
const activeCounties = counties.filter(c => c.customersOut > 0).length;

// Compare only fields that should create a notification.
// We intentionally do NOT compare "customers served" so a routine customer-count
// adjustment does not generate a false outage notification.
const canonical = {
  totalCustomersOut,
  totalOutages,
  counties: counties.map(county => ({
    state: county.state,
    county: county.county,
    customersOut: county.customersOut,
    totalOutages: county.totalOutages,
    municipalities: county.municipalities.map(town => ({
      municipality: town.municipality,
      customersOut: town.customersOut,
      etr: town.etrRaw,
    })),
  })),
};

const signature = JSON.stringify(canonical);

const store = $getWorkflowStaticData('global');
const previous = store.oruStateV1 || null;

const isFirstRun = !previous?.signature;
const changed = !isFirstRun && previous.signature !== signature;

let shouldSend = false;
let changeType = 'NO_CHANGE';

if (isFirstRun) {
  shouldSend = Boolean(cfg.sendFirstRunIfActive) && totalCustomersOut > 0;
  changeType = shouldSend ? 'FIRST_ACTIVE' : 'FIRST_BASELINE';
} else if (changed) {
  shouldSend = true;

  if (n(previous.totalCustomersOut) > 0 && totalCustomersOut === 0) {
    changeType = 'RESTORED';
  } else if (totalCustomersOut > n(previous.totalCustomersOut)) {
    changeType = 'INCREASED';
  } else if (totalCustomersOut < n(previous.totalCustomersOut)) {
    changeType = 'DECREASED';
  } else {
    changeType = 'DETAIL_CHANGED';
  }
}

const lines = [];

lines.push(`${formatNumber(totalCustomersOut)} CUSTOMERS OUT`);
lines.push(
  `${formatNumber(activeMunicipalities)} ACTIVE ` +
  `${activeMunicipalities === 1 ? 'MUNICIPALITY' : 'MUNICIPALITIES'}`
);
lines.push(`${formatNumber(counties.length)} COUNTIES`);
lines.push('');

for (const state of states) {
  lines.push(state.state === 'NJ' ? 'NEW JERSEY' : 'NEW YORK');

  for (const county of state.counties) {
    const countyName = county.county.toUpperCase();

    if (county.customersOut > 0) {
      lines.push(
        `🔴 ${countyName} COUNTY — ${formatNumber(county.customersOut)} OUT`
      );

      for (const town of county.municipalities) {
        lines.push(`  • ${town.municipality}`);
        lines.push(
          `    ${formatNumber(town.customersOut)} of ` +
          `${formatNumber(town.customersServed)} out ` +
          `(${percentLabel(town.customersOut, town.customersServed)})`
        );

        if (town.etr !== '--') {
          lines.push(`    ETR ${town.etr}`);
        }
      }
    } else {
      lines.push(`🟢 ${countyName} COUNTY — CLEAR`);
    }

    lines.push('');
  }
}

const updated = generationTime(directory);
lines.push(`Updated ${updated}`);

const title =
  totalCustomersOut > 0
    ? `ORU - ${formatNumber(totalCustomersOut)} Out | ${formatNumber(activeMunicipalities)} Town${activeMunicipalities === 1 ? '' : 's'}`
    : 'ORU - All Clear';

const ntfy = {
  topic: cfg.ntfyTopic,
  title,
  message: lines.join('\n'),
  priority: totalCustomersOut > 0 ? 5 : 3,
  tags: totalCustomersOut > 0
    ? ['warning', 'zap']
    : ['white_check_mark'],
  markdown: false,
  click: cfg.mapUrl,
  actions: [
    {
      action: 'view',
      label: 'ORU Map',
      url: cfg.mapUrl,
      clear: false,
    }
  ]
};

return [{
  json: {
    shouldSend,
    changeType,
    directory,
    updated,
    signature,

    totalCustomersOut,
    totalOutages,
    activeCounties,
    activeMunicipalities,
    countyCount: counties.length,

    states,
    ntfy,
  }
}];

const result = $('Process ORU').first().json;
const store = $getWorkflowStaticData('global');

store.oruStateV1 = {
  signature: result.signature,
  totalCustomersOut: result.totalCustomersOut,
  totalOutages: result.totalOutages,
  activeMunicipalities: result.activeMunicipalities,
  directory: result.directory,
  updated: result.updated,
  savedAt: new Date().toISOString(),
};

return [{
  json: {
    saved: true,
    shouldSend: result.shouldSend,
    changeType: result.changeType,
    totalCustomersOut: result.totalCustomersOut,
    activeMunicipalities: result.activeMunicipalities,
    directory: result.directory,
    updated: result.updated,
  }
}];

function hashId(value) {
  let hash = 2166136261;
  value = String(value || '');
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

return $input.all().map((item) => {
  const j = item.json || {};
  const p = j.ntfy || {};
  const totalOut = Number(j.totalCustomersOut || 0);
  const change = String(j.changeType || 'UPDATE').toUpperCase();
  const title = String(p.title || 'ORU Outage Update').trim();
  const message = String(p.message || '').trim();
  const now = new Date().toISOString();

  const sourceEventId = hashId(
    String(j.directory || '') + '|' +
    String(j.signature || '') + '|' +
    title + '|' + message
  );

  let status = totalOut > 0 ? 'ACTIVE' : 'RESOLVED';
  let eventAction = 'UPDATE';

  if (change === 'FIRST_ACTIVE') eventAction = 'NEW';
  if (change === 'RESTORED') eventAction = 'RESOLVED';

  const alert = {
    schema_version: '1.0',
    alert_id: `ORU:${sourceEventId}`,
    source: 'ORU',
    source_event_id: sourceEventId,
    category: 'UTILITY',
    subtype: 'POWER_OUTAGE',
    status,
    event_action: eventAction,
    title,
    message: message || 'ORU outage status changed.',
    priority: Number(p.priority || (totalOut > 0 ? 5 : 3)),
    county: '',
    municipality: '',
    location: {
      label: 'ORU service territory',
      address: '',
      state: '',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['oru', 'utility', 'power-outage'],
    click_url: String(p.click || ''),
    source_url: String(p.click || ''),
    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,
    metadata: {
      change_type: change,
      total_customers_out: totalOut,
      total_outages: Number(j.totalOutages || 0),
      active_counties: Number(j.activeCounties || 0),
      active_municipalities: Number(j.activeMunicipalities || 0),
      states: j.states || []
    }
  };

  alert.search_text = [
    alert.source, alert.category, alert.subtype,
    alert.status, alert.title, alert.message,
    ...alert.tags
  ].filter(Boolean).join(' ');

  return { json: alert };
});
